/// <summary>
/// This is a controller class which initializes the service class.
/// </summary>
class METVendorChangeRequestController extends SysOpSampleBaseController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// This is the caption for the vendor change request batch job.
/// </summary>
/// <returns>Returns the caption.</returns>
public ClassDescription caption()
{
    return "@MET:VendChangeReqBatch";
}

    /// <summary>
    /// Initializes new memory for METVendorChangeRequestController class.
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METVendorChangeRequestService));
        this.parmMethodName(methodStr(METVendorChangeRequestService, processOperation));
    }

    /// <summary>
    /// This is the main method where the process starts.
    /// </summary>
    /// <param name = "_args">_args</param>
    public static void main(Args _args)
    {
        METVendorChangeRequestController operation;

        operation = new METVendorChangeRequestController();
        operation.startOperation();
    }

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Construct method
/// </summary>
/// <returns>METVendorChangeRequestController</returns>
public static METVendorChangeRequestController construct()
{
    return new METVendorChangeRequestController();
}
